uint8_t is_valid_lifting_size (uint16_t lifting_size) {
    for (int i = 0; i < sizeof (lifting_sizes)/sizeof(uint16_t); i++) {
        if (lifting_sizes [i] == lifting_size) {
            return 1;
        }
    }
    return 0;
}

uint16_t get_nearest_lifting_size (uint16_t msg_len, uint16_t code_len) {
    uint16_t lifting_size = DIV_CEIL(msg_len, BG1_COLS - BG1_ROWS);
    if (DIV_CEIL(code_len - msg_len, lifting_size) > BG1_ROWS) {
        lifting_size = (code_len - msg_len + BG1_ROWS - 1) / BG1_ROWS;
    }

    for (int i = 0; i < sizeof (lifting_sizes)/sizeof(uint16_t); i++) {
        if (lifting_sizes [i] >= lifting_size) {
            return lifting_sizes [i];
        }
    }

    return 0;
}

int8_t get_set_index (uint16_t lifting_size) {
    for (int i = 0; i < sizeof (lifting_sizes)/sizeof(uint16_t); i++) {
        if (lifting_sizes [i] == lifting_size) {
            return set_indices [i];
        }
    }
    return -1;
}

